2060:                      glmfails="$2"; shift 2 ;;
2061:      --glm-lock-busy) lockbusy=1;   shift ;;
2062:      --force)        force=1;       shift ;;
2063:      --kimi-fit)     kimi_fit=1;    shift ;;
2064:      --spawn)        spawn=1;       shift ;;  # default; kept explicit for callers/back-compat
2065:      --no-spawn)     spawn=0;       shift ;;  # resolve+journal only, no worker launched (tests)
2070:                          lane_writes="$2"; shift 2 ;;
2072:                          lane_acceptance_cmd="$2"; shift 2 ;;
2073:      --rollback-onestep) lane_rollback=1; shift ;;
2075:                      founder_task_id="$2"; shift 2 ;;
2078:      *)              mission="${mission}${mission:+ }$1"; shift ;;  # collect positional mission
2333:  # R1 FIX (Finding 3): --force NEVER bypasses the duplicate-task_sig refusal in the
2334:  # automated path. The router itself never sets an override; --force is still accepted
2648:  record-review) shift; cmd_record_review "$@" ;;

